const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
beforeAll(() => ctx.initialize())
afterEach(() => ctx.cleanup())

const RECORD_ACTION = `action="INSERT_OR_UPDATE"`
function xmlRecordRegex(table: string) {
    return new RegExp(`<${table} ${RECORD_ACTION}>[\\s\\S]*?<\\/${table}>`, 'g')
}

